---@alias gcp.unstable.displayvideo_v2.LineItemEntityStatusEnum "ENTITY_STATUS_UNSPECIFIED"|"ENTITY_STATUS_ACTIVE"|"ENTITY_STATUS_ARCHIVED"|"ENTITY_STATUS_DRAFT"|"ENTITY_STATUS_PAUSED"|"ENTITY_STATUS_SCHEDULED_FOR_DELETION"

